    fn contract() {
let mut out=Vec::with_capacity(16); out.push(99); let p=out.as_ptr(); let c=out.capacity();
refill(&mut out,&[2,3]); assert_eq!(out,[4,6]); assert_eq!(out.as_ptr(),p); assert_eq!(out.capacity(),c);
refill(&mut out,&[]); assert!(out.is_empty()); assert_eq!(out.as_ptr(),p);
    }
}

