use std::cell::Cell;
struct Guard<'a>(&'a Cell<usize>);
impl Drop for Guard<'_> { fn drop(&mut self) { self.0.set(self.0.get()+1); } }
fn released() -> usize {
    let count=Cell::new(0);
    { let _guard = Guard(&count); }
    count.get()
}
fn main() {}

